def Q(x, a):
    return 64 * x**2 + a * x - 486

def check_initial_ratios(a):
    # Check the first 4 terms for a stable ratio starting from k=0
    k_values = [0, 1, 2, 3]
    values = [Q(k, a) for k in k_values]

    print(f"--- Testing a = {a} ---")
    print(f"Q(0)={values[0]}, Q(1)={values[1]}, Q(2)={values[2]}, Q(3)={values[3]}")

    ratios = []
    for i in range(3):
        if values[i] != 0 and values[i+1] % values[i] == 0:
            r = values[i+1] / values[i]
            ratios.append(r)
        elif values[i+1] == 0 and values[i] != 0:
             ratios.append(0)
        elif values[i+1] != 0 and values[i] == 0:
             ratios.append("Undefined")
        else:
             ratios.append(values[i+1] / values[i])

    # Check if the ratios are equal (or very close if floating point)
    if len(set(ratios)) == 1 and all(isinstance(r, (int, float)) for r in ratios):
         print("Ratios are constant (Potential GP starting at k=0)")
    else:
        print("Ratios are not constant or sequence does not start as GP.")

# Test specific values of a
test_values = [-1, 0, 1, -243, 486]
for a in test_values:
    check_initial_ratios(a)
